export function initHelpChat({account}){
 const button=document.createElement('button');button.type='button';button.className='support-launcher';button.setAttribute('aria-label','Abrir ajuda para tirar dúvidas');button.innerHTML='<img src="/assets/favicon.webp" alt="" width="44" height="44"><span>Dúvidas?</span>';document.body.append(button);
 const dialog=document.createElement('dialog');dialog.className='help-dialog';dialog.setAttribute('aria-labelledby','help-title');dialog.innerHTML='<header><div><p class="help-eyebrow">CAPIMIMO · AJUDA</p><h2 id="help-title">Como podemos ajudar?</h2></div><button type="button" class="help-close" aria-label="Fechar ajuda">Fechar</button></header><p>Sou a ajuda automática. Posso explicar os planos e como criar seu presente.</p><p class="help-privacy">Sua pergunta é processada por IA da Cloudflare. Não envie senha, código de acesso, dados de cartão ou informações pessoais sensíveis.</p><div class="help-messages" aria-label="Conversa" aria-live="polite"></div><form class="help-form"><label for="help-question">Sua pergunta</label><textarea id="help-question" name="question" maxlength="500" rows="3" required placeholder="Ex.: Como recebo meu presente?"></textarea><button type="submit" class="help-send">Enviar pergunta</button></form><p class="help-status" role="status"></p><div class="help-human"><p>Precisa de ajuda com uma compra ou quer falar com uma pessoa?</p><button type="button" class="help-open-human">Falar com a equipe</button><small>Para manter sua conversa privada, você entrará com seu e-mail. A resposta fica disponível em Minha conta.</small></div>';document.body.append(dialog);
 const $=s=>dialog.querySelector(s),form=$('.help-form'),status=$('.help-status'),messages=$('.help-messages');let version=0,busy=false;
 function add(label,text){const item=document.createElement('article'),who=document.createElement('strong'),body=document.createElement('p');who.textContent=label;body.textContent=text;item.append(who,body);messages.append(item);item.scrollIntoView({block:'nearest'});}
 function clear(){version++;busy=false;form.reset();$('.help-send').disabled=false;status.textContent='';messages.replaceChildren();}
 button.addEventListener('click',()=>{if(dialog.open)return;clear();dialog.showModal();$('#help-question').focus();});$('.help-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',clear);
 $('.help-open-human').addEventListener('click',()=>{dialog.close();account.openSupport();});
 form.addEventListener('submit',async event=>{event.preventDefault();if(busy||!form.reportValidity())return;const question=$('#help-question').value.trim();if(!question){status.textContent='Escreva sua pergunta.';return;}const own=++version;busy=true;$('.help-send').disabled=true;status.textContent='Buscando uma resposta…';try{const response=await fetch('/api/help/answer',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({question}),signal:AbortSignal.timeout(30000)});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'Não foi possível responder agora.');if(own!==version||!dialog.open)return;add('Você',question);add('Ajuda automática',typeof data.answer==='string'?data.answer:'Fale com nossa equipe para receber ajuda.');form.reset();status.textContent=data.handoff?'Nossa equipe pode ajudar com essa questão.':'Resposta gerada por IA. Confira as informações antes de decidir.';}catch(error){if(own===version&&dialog.open)status.textContent=error.message||'Não foi possível responder agora. Tente novamente ou fale com a equipe.';}finally{if(own===version){busy=false;$('.help-send').disabled=false;}}});
 return {button,dialog};
}
